      '最大の相手は、北方の遊牧国家匈奴でした。それまで漢は、建国者の劉邦が敗れて以来、匈奴に貢ぎ物をおくって和平を保っていました。武帝はこの屈辱的な関係をひっくり返そうと、将軍衛青や、その甥で20歳前後の霍去病を送りこんで匈奴を打ち破りました。さらに西の河西回廊をおさえて敦煌などの郡を置き、西域への道を開きます。南はベトナム北部、東は朝鮮半島北部まで支配を広げ、漢の領土は最大になりました。',
