      'ところが皇帝になった彼は、驚くほど「聞く耳」をもつ君主になります。とくに有名なのが、もとは兄の部下だった魏徴を重く用いたことです。魏徴は200回以上も皇帝に面と向かって意見したといわれ、太宗が腹を立てても引き下がりませんでした。太宗はそれを受け入れ、魏徴が亡くなると「鏡を一つ失った」と嘆いたと伝えられます。かつての敵の部下を信頼したところに、彼の度量の大きさがあらわれています。',
