      'チンギス=カンの子ども時代は、苦難の連続でした。幼名はテムジンといいます。9歳ごろ、部族の長だった父が敵対するタタル部に毒殺され、家族は仲間から見捨てられてしまいました。母と兄弟たちは、草の根や魚をとって飢えをしのいだといいます。若いころには敵につかまったり、妻をさらわれたりもしました。その中で、彼は信頼できる仲間を一人ずつ増やしていったのです。',
      '当時のモンゴル高原では、多くの部族が争っていました。テムジンは戦いと同盟を重ね、1206年、ついに高原の遊牧民をまとめあげ、クリルタイでチンギス=カンの称号を受けました。ここで彼は大胆な改革をします。昔からの部族のまとまりをいったんばらして、遊牧民を1000戸ずつのグループ（千戸制）に組み直し、自分が信頼する部下をその長にしたのです。こうして「血筋」ではなく「チンギスへの忠誠」で動く、強い軍隊ができあがりました。',
      'モンゴル軍の強みは、すばやい騎馬の機動力と、まわりの国の技術や情報を取りこむ柔軟さでした。チンギスは中国北部の金を攻めて都を落とし、さらに西のホラズム=シャー朝が送った使節団や商人を殺したことに怒って、中央アジアへ大遠征しました。抵抗した都市には徹底した攻撃を加え、降伏した都市は許す――このやり方で、征服地はみるみる広がりました。',
      '1227年、チンギスは西夏を攻める途中で亡くなりました。その墓の場所は秘密にされ、今もわかっていません。彼の死後、子や孫たちがさらに征服を続け、モンゴル帝国は東はユーラシアの東端から西は東ヨーロッパまで広がる、史上最大級の陸の帝国になります。征服のきびしさの一方で、帝国の中の交通や交易は安全になり、東西の人と物の往来がさかんになりました。'
