      { title: '源義経がチンギス=カン？', text: '日本には、平泉で死んだはずの源義経が大陸に渡ってチンギス=カンになった、という説が明治以降に広まりました。しかし年代も記録もまったく合わず、歴史学では否定されています。', legend: true }
