    legacy: 'チンギス=カンのつくったモンゴル帝国は、ユーラシアの東西を一つの政治的まとまりでつなぎました。その結果、駅伝制（ジャムチ）のもとで人・物・情報の行き来がさかんになり、のちの「大航海時代」につながる世界の一体化の先がけとなりました。現在のモンゴル国では建国の英雄として敬われています。',
