      'フビライは、外国人を役人として使うことに積極的でした。マルコはフビライに仕え、使者として中国の各地をまわったと語っています。彼が見た中国は、ヨーロッパよりはるかに大きな都市、運河を行き交う船、紙でできたお金、そして「燃える黒い石」（石炭）などにあふれた世界でした。約17年の滞在のあと、イル=ハン国に嫁ぐ王女をおくる一行に加わり、海の道で帰国しました。',
