      'なぜそれほど旅を続けられたのでしょうか。カギは、当時のイスラーム世界の広がりです。モロッコからインド、東南アジアまで、各地にイスラーム教徒の町があり、アラビア語が通じ、同じイスラーム法（シャリーア）が使われていました。だから法学者である彼は、行く先々で歓迎され、時には裁判官として雇われることもありました。インドのデリーでは、トゥグルク朝のスルタンに法官として約8年も仕えています。',
