      '1838年、道光帝は林則徐を欽差大臣（皇帝の全権を与えられた特使）に任じて広州に送りました。林則徐は着任するとすぐにイギリス商人の商館を包囲し、アヘンをすべて差し出させます。その量は2万箱以上、重さにして約1400トンにのぼりました。彼はこれを虎門の海岸で、大きな池に塩と石灰と混ぜて溶かし、海に流して処分しました。作業には3週間ほどかかったといいます。',
