      '最大の山場は800年のクリスマスです。ローマのサン=ピエトロ大聖堂で祈りをささげていたカールの頭に、教皇レオ3世が冠をのせ、「ローマ皇帝」と宣言しました。西ローマ帝国が滅んでから300年あまりのことです。ローマ教会は、ビザンツ帝国にたよらずに自分たちを守ってくれる強い保護者を求めていましたし、カールも皇帝の権威を必要としていました。こうして「ローマ」「キリスト教」「ゲルマン」の3つの要素がひとつになり、西ヨーロッパ世界が誕生したといわれます。',
      'カールは広い国を治めるため、各地を伯という役人に治めさせ、さらに巡察使を送って監督させました。また、イギリスから学者アルクインらを招き、都のアーヘンの宮廷に学校を開きました。ラテン語の古典を写本して守り、読みやすい新しい書体をつくらせます。この文化の復興を「カロリング=ルネサンス」とよびます。今のアルファベットの小文字は、このときの書体がもとになっています。',
