      '女王はまず、宗教の争いをおさめるために、1559年の統一法でイギリス国教会を確立しました。教えはプロテスタント寄り、儀式はカトリックの形も残すという、両方に配慮した中間の道でした。そして財政の再建をすすめ、重臣セシルらの意見をよく聞いて、慎重に国を運営しました。「悪貨は良貨を駆逐する」で知られる財政家グレシャムも、この時代の王室に仕えています。',
