      { title: 'ホッブズとのちがい', text: '同じ社会契約説でも、ホッブズは『リヴァイアサン』で、自然のままでは「万人の万人に対する闘争」になるので、強い主権者に権利を委ねるべきだと説きました。ロックは、権利を委ねても抵抗権は残る、と考えました。' }
