    legacy: 'ロックの自然権・社会契約・抵抗権の思想は、アメリカ独立宣言やフランス人権宣言に受けつがれ、近代民主主義と立憲政治の理論的な柱となりました。経験を重んじる哲学は、イギリス経験論として啓蒙思想に影響を与えました。',
    terms: ['名誉革命', '『統治二論』', '自然権', '社会契約説', '抵抗権', 'イギリス経験論', 'ホッブズ', 'アメリカ独立宣言']
