      { title: '木の入れ歯？', text: 'ワシントンは歯が悪く、入れ歯を使っていました。「木の入れ歯」とよくいわれますが、実際はカバの牙や動物・人間の歯でつくられていました。その中には、奴隷にされていた人びとから買った歯がふくまれていた可能性も指摘されています。' }
