    legacy: '権力の座にとどまらず、自ら身を引いたワシントンの姿勢は、軍人が政治を支配せず、平和的に権力が受けつがれる共和政の伝統を合衆国に根づかせました。首都ワシントンD.C.をはじめ、多くの地名に彼の名が残っています。1ドル紙幣の肖像も彼です。',
