      { year: 1792, text: '国民公会の議員となる' },
      { year: 1793, text: '1月に国王ルイ16世が処刑される。7月、公安委員会に加わり恐怖政治を進める' },
      { year: 1794, text: '2月、植民地の奴隷制廃止が国民公会で決まる。4月、ダントンらを処刑' },
      { year: 1794, text: '7月、テルミドールのクーデタで逮捕され、翌日処刑される' }
