    quote: { text: '徳なき恐怖は有害であり、恐怖なき徳は無力である', note: '1794年2月の国民公会での演説の趣旨です。革命を守るための恐怖政治を正当化したものです。' },
    legacy: 'ロベスピエールの時代に、男性普通選挙をうたった1793年憲法や封建的特権の無償廃止など、急進的な改革が進められました。一方、恐怖政治は、理想を掲げた革命が暴力へと向かう危うさを示す例として、今も議論されつづけています。',
