      { title: 'フランスがくしゃみをすると', text: '「フランスがくしゃみをすると、ヨーロッパがかぜをひく」はメッテルニヒの言葉とされることが多いのですが、確かな出典ははっきりしません。フランスの革命がヨーロッパ中に広がることを警戒した気持ちをよくあらわしています。', legend: true }
