    legacy: 'メッテルニヒが中心となったウィーン体制は、大国の勢力均衡によって約40年間、ヨーロッパに大きな戦争のない時代をもたらしました。一方、自由主義と民族運動をおさえつけたことで、1848年の革命の爆発を招くことになりました。',
    terms: ['ウィーン会議', '正統主義', '勢力均衡', 'ウィーン体制', '四国同盟', '神聖同盟', '1848年革命']
