      { title: 'エンゲルスの仕送り', text: 'エンゲルスは父の会社で働きながら、マルクスの家族に長年にわたって仕送りを続けました。マルクスの死後は、残された原稿を整理して『資本論』の第2巻・第3巻を出版しました。' }
