      '当時のアメリカでは、南部の州は綿花の大農園で黒人奴隷を使い、北部の州は工業が発達して奴隷制がありませんでした。新しく西部にできる州で奴隷制を認めるかどうかが、大きな争いになっていました。リンカンは「分かれた家は立っていられない」と演説し、奴隷制の拡大に反対しました。1860年、共和党の候補として彼が大統領に当選すると、南部の州は次々と合衆国から離脱し、アメリカ連合国をつくりました。',
