    life: [
      { year: 1878, text: 'ジョージア（グルジア）のゴリで靴職人の子として生まれる' },
      { year: 1922, text: '共産党の書記長となる' },
      { year: 1924, text: 'レーニンが死去。一国社会主義論を唱え、トロツキーと対立' },
      { year: 1928, text: '第1次五か年計画を始め、農業の集団化を進める' },
      { year: 1936, text: '大粛清が本格化する（〜1938年）' },
      { year: 1939, text: 'ドイツと独ソ不可侵条約を結ぶ' },
      { year: 1941, text: 'ドイツがソ連に侵攻し、独ソ戦が始まる' },
      { year: 1943, text: 'スターリングラードの戦いでドイツ軍を降伏させる' },
      { year: 1945, text: 'ヤルタ会談・ポツダム会談に出席' },
      { year: 1953, text: '死去' }
    ],
    story: [
      'スターリンは本名をジュガシヴィリといい、ロシア帝国の南、ジョージアの貧しい靴職人の家に生まれました。神学校で学びましたが、革命運動に加わって退学になります。「スターリン」は「鋼鉄の人」という意味の名前で、革命家として活動するうちに名のるようになりました。レーニンのもとで共産党の書記長になると、党の人事をにぎり、目立たないながらも着実に力をたくわえていきました。',
      'レーニンが亡くなると、後継者争いが始まりました。世界革命を唱えるトロツキーに対し、スターリンは「ソ連一国だけでも社会主義は建設できる」という一国社会主義論を唱えて勝利しました。そして1928年から五か年計画を始め、重工業の建設を猛スピードで進めます。同時に、農民の土地や家畜を集めて集団農場（コルホーズ）をつくらせました。反対する農民は追放され、ウクライナなどでは大ききんが起こり、数百万人ともいわれる人が亡くなりました。',
      'こうしてソ連は短期間で工業大国となりました。世界恐慌で資本主義国が苦しむ中、ソ連だけが成長を続けたように見えたのです。しかし、その裏でスターリンは、反対派だけでなく党の幹部や軍の将校、ふつうの人びとまで、「人民の敵」として次々に逮捕・処刑し、強制収容所に送りました。これを大粛清といいます。人びとは密告におびえて暮らし、スターリンは神のようにあがめられる個人崇拝の対象となりました。',
      '1939年、スターリンはヒトラーと独ソ不可侵条約を結んで世界をおどろかせましたが、1941年、そのドイツに攻めこまれます。独ソ戦はソ連だけで2000万人以上ともいわれる死者を出す凄惨な戦いになりましたが、スターリングラードの戦いを転機にドイツを押し返し、ベルリンまで攻めこみました。戦後は東ヨーロッパに社会主義の国々をつくり、アメリカとの冷戦が始まります。1953年に亡くなると、3年後にフルシチョフがその独裁を批判しました。'
    ],
    episodes: [
      { title: '写真から消された人びと', text: 'スターリン時代のソ連では、粛清された人物が公式の写真から修整して消されることがありました。歴史そのものを書きかえようとしたのです。' },
      { title: 'スターリン批判', text: '1956年、フルシチョフは党大会の秘密報告で、スターリンの個人崇拝と大粛清を批判しました。この報告は世界に衝撃を与え、東ヨーロッパの民衆の運動にもつながりました。' }
    ],
    legacy: 'スターリンの計画経済によってソ連は工業大国となり、第二次世界大戦でドイツを破る力をもちましたが、その過程では集団化によるききんや大粛清で膨大な犠牲が生まれました。戦後の東欧支配は、冷戦によるヨーロッパの分断を生みました。',
    terms: ['一国社会主義論', '五か年計画', 'コルホーズ', '大粛清', '独ソ不可侵条約', '独ソ戦', 'スターリングラードの戦い', '冷戦']
