      'フランクリン=ローズヴェルトは、ニューヨークの名家に生まれ、親戚には大統領セオドア=ローズヴェルトがいました。順調に政治家の道を歩んでいた彼を、39歳のとき病気が襲います。ポリオにかかって両足が動かなくなったのです。それでも彼はあきらめず、リハビリを続けて政界に復帰しました。公の場では足の装具と杖で立ち、車いすの姿を写真に撮らせないよう気をつけていたといいます。',
      '1932年、彼が大統領選挙に勝ったとき、アメリカは世界恐慌のどん底にありました。銀行は次々につぶれ、4人に1人が失業していました。就任演説で彼は「われわれが恐れなければならない唯一のものは、恐れそのものである」と語り、人びとを励ましました。そしてすぐに「ニューディール（新規まき直し）」とよばれる政策を次々と打ち出します。就任後の最初の100日間で成立させた法律は、15にのぼりました。',
      'ニューディールの特徴は、それまでの「政府は経済に口を出さない」という考えを転換し、国が積極的に経済に関わったことです。農産物の生産を調整し、テネシー川流域開発公社（TVA）でダムを建設して雇用を生み出し、労働者が組合をつくる権利を認め、年金などの社会保障制度をつくりました。またラジオで「炉辺談話」という語りかけを行い、国民に直接政策を説明しました。',
      '第二次世界大戦が始まると、ローズヴェルトは「民主主義の兵器庫」として、イギリスなどに武器を送りました。1941年にはチャーチルと大西洋憲章を発表し、戦後の世界のあり方を示しました。同じ年、日本の真珠湾攻撃でアメリカは参戦します。彼は史上ただ一人、4回も大統領に選ばれましたが、1945年4月、戦争の終わりを見ずに亡くなりました。国際連合の設立も、彼が力を注いだ構想でした。'
