    quote: { text: 'われわれが恐れなければならない唯一のものは、恐れそのものである', note: '1933年3月の大統領就任演説の一節です。恐慌で不安におちいる国民を励ました言葉です。' },
    legacy: 'ニューディールは、政府が経済に積極的に関わり、社会保障で国民の生活を支える「大きな政府」の考え方をアメリカに定着させました。1935年の社会保障法は、今もアメリカの年金制度の土台です。大西洋憲章や国際連合の構想は、戦後の国際秩序の土台となりました。',
