      '1940年5月、ドイツ軍がフランスに攻めこむと、イギリスは絶体絶命の危機におちいりました。そこで首相に選ばれたのが、65歳のチャーチルでした。就任直後の演説で「私が差し出せるのは、血と労苦と涙と汗だけだ」と語り、ナチ=ドイツと最後まで戦うことを国民に訴えました。ドイツ空軍の激しい空襲（バトル=オブ=ブリテン）にも屈せず、アメリカのローズヴェルトと協力して、連合国の勝利に貢献しました。',
