      '第一次世界大戦が始まると、アメリカははじめ中立を守りました。しかし、ドイツが中立国の船まで無差別に攻撃する無制限潜水艦作戦を始めると、1917年、ついに参戦を決めます。ウィルソンはこの戦争を「民主主義のために世界を安全にする」戦いだと位置づけました。アメリカの参戦によって、連合国側の勝利は決定的となりました。',
      '1918年1月、ウィルソンは戦後の平和のための原則として「十四か条」を発表しました。秘密外交の廃止、海洋の自由、軍備の縮小、民族自決、そして国際平和機構の設立などです。ロシアの革命政権が「平和に関する布告」を出したことに対抗する意味もありました。1919年のパリ講和会議に、ウィルソンは自ら乗りこみました。現職のアメリカ大統領がヨーロッパに行くのは初めてのことで、彼は熱狂的に迎えられました。',
